data class Point(val x: Double, val y: Double)

fun antColonyOptimization(
    points: List<Point>,
    alpha: Double = 1.0,
    beta: Double = 2.0,
    rho: Double = 0.1,
    Q: Double = 1.0,
    tau0: Double = 1.0,
    maxIterations: Int = 1000
): List<Point> {
    val n = points.size

    when (n) {
        0 -> return emptyList()
        1 -> return points
        2 -> return points
    }

    val dist = Array(n) { i ->
        DoubleArray(n) { j ->
            if (i == j) 0.0
            else {
                val dx = points[i].x - points[j].x
                val dy = points[i].y - points[j].y
                kotlin.math.hypot(dx, dy)
            }
        }
    }

    val eta = Array(n) { i ->
        DoubleArray(n) { j ->
            if (i == j) 0.0 else 1.0 / dist[i][j]
        }
    }

    val pheromone = Array(n) { DoubleArray(n) { tau0 } }

    var bestTour: List<Int> = emptyList()
    var bestLength = Double.POSITIVE_INFINITY

    var iteration = 0
    var converged = false

    while (!converged && iteration < maxIterations) {
        iteration++

        val tours = Array(n) { mutableListOf<Int>() }
        val lengths = DoubleArray(n)

        for (ant in 0 until n) {
            val visited = BooleanArray(n)
            val tour = mutableListOf<Int>()
            val start = ant
            tour.add(start)
            visited[start] = true
            var current = start

            while (tour.size < n) {
                val allowed = (0 until n).filter { !visited[it] }

                val probabilities = DoubleArray(allowed.size)
                var sumProb = 0.0
                for ((idx, next) in allowed.withIndex()) {
                    val prob = pheromone[current][next].pow(alpha) * eta[current][next].pow(beta)
                    probabilities[idx] = prob
                    sumProb += prob
                }

                var rand = Random.nextDouble() * sumProb
                var chosen = -1
                for ((idx, next) in allowed.withIndex()) {
                    rand -= probabilities[idx]
                    if (rand <= 0.0) {
                        chosen = next
                        break
                    }
                }
                if (chosen == -1) chosen = allowed.last()

                tour.add(chosen)
                visited[chosen] = true
                current = chosen
            }

            val fullTour = tour.toList()
            tours[ant] = fullTour.toMutableList()
            var length = 0.0
            for (i in 0 until n - 1) {
                length += dist[fullTour[i]][fullTour[i + 1]]
            }
            length += dist[fullTour.last()][fullTour.first()]
            lengths[ant] = length

            if (length < bestLength) {
                bestLength = length
                bestTour = fullTour
            }
        }

        for (i in 0 until n) {
            for (j in 0 until n) {
                pheromone[i][j] *= (1 - rho)
            }
        }
        for (ant in 0 until n) {
            val tour = tours[ant]
            val length = lengths[ant]
            val delta = Q / length
            for (k in 0 until n - 1) {
                val i = tour[k]
                val j = tour[k + 1]
                pheromone[i][j] += delta
                pheromone[j][i] += delta
            }
            val last = tour.last()
            val first = tour.first()
            pheromone[last][first] += delta
            pheromone[first][last] += delta
        }


        if (n > 1) {
            fun tourToEdgeSet(tour: List<Int>): Set<Pair<Int, Int>> {
                val edges = mutableSetOf<Pair<Int, Int>>()
                for (i in 0 until tour.size - 1) {
                    val a = tour[i]
                    val b = tour[i + 1]
                    edges.add(if (a < b) a to b else b to a)
                }
                val a = tour.last()
                val b = tour.first()
                edges.add(if (a < b) a to b else b to a)
                return edges
            }

            val firstEdges = tourToEdgeSet(tours[0])
            val allSame = tours.all { tourToEdgeSet(it) == firstEdges }
            if (allSame) {
                converged = true
            }
        }
    }

    return bestTour.map { points[it] }
}


data class Obshepit(
    val row: Int,
    val col: Int,
    val title: String,
    val description: String = "",
    val workingHours: String = "",
    val type: String = ""
)

object MapConfig {
    fun logLongString(tag: String, text: String) {
        val chunkSize = 4000
        var i = 0
        while (i < text.length) {
            val end = (i + chunkSize).coerceAtMost(text.length)
            Log.d(tag, text.substring(i, end))
            i += chunkSize
        }
    }
    var SAVED_GRID = ""

    var SAVED_FOOD_PLACES =
        "80,61,Новый общепит,Описание,08:00-18:00,Кафе;84,63,Новый общепит,Описание,08:00-18:00,Кафе;76,71,Новый общепит,Описание,08:00-18:00,Кафе;66,71,Новый общепит,Описание,08:00-18:00,Кафе;68,83,Новый общепит,Описание,08:00-18:00,Кафе;83,85,Новый общепит,Описание,08:00-18:00,Кафе"
}

fun exportGridToString(grid: Array<BooleanArray>): String {
    val sb = StringBuilder()
    for (row in grid) {
        for (cell in row) sb.append(if (cell) "1" else "0")
    }
    return sb.toString()
}

fun importGridFromString(data: String): Array<BooleanArray> {
    if (data.length != ROWS * COLS) {
        return Array(ROWS) { BooleanArray(COLS) { false } }
    }

    val grid = Array(ROWS) { BooleanArray(COLS) }
    var index = 0
    for (r in 0 until ROWS) {
        for (c in 0 until COLS) {
            grid[r][c] = data[index] == '1'
            index++
        }
    }
    return grid
}

fun exportFoodPlacesToString(foodPlaces: List<Obshepit>): String {
    return foodPlaces.joinToString(";") { place ->
        listOf(
            place.row.toString(),
            place.col.toString(),
            place.title.replace(",", " ").replace(";", " "),
            place.description.replace(",", " ").replace(";", " "),
            place.workingHours.replace(",", " ").replace(";", " "),
            place.type.replace(",", " ").replace(";", " ")
        ).joinToString(",")
    }
}

fun importFoodPlacesFromString(data: String): MutableList<Obshepit> {
    if (data.isBlank()) return mutableListOf()

    return data.split(";").mapNotNull { item ->
        val parts = item.split(",")
        if (parts.size < 6) return@mapNotNull null

        val row = parts[0].toIntOrNull() ?: return@mapNotNull null
        val col = parts[1].toIntOrNull() ?: return@mapNotNull null

        Obshepit(
            row = row,
            col = col,
            title = parts[2],
            description = parts[3],
            workingHours = parts[4],
            type = parts[5]
        )
    }.toMutableList()
}

// A*
data class Node(
    val r: Int,
    val c: Int,
    var g: Int = 0,
    var h: Int = 0,
    var parent: Node? = null
) {
    val f get() = g + h
}

class AStarPathfinder(private val grid: Array<BooleanArray>) {
    fun findPath(sr: Int, sc: Int, er: Int, ec: Int): List<Pair<Int, Int>> {
        val open = mutableListOf(Node(sr, sc))
        val closed = mutableSetOf<Pair<Int, Int>>()

        val gCost = Array(ROWS) { IntArray(COLS) { Int.MAX_VALUE } }
        gCost[sr][sc] = 0
        while (open.isNotEmpty()) {
            val curr = open.minByOrNull { it.f }!!
            if (curr.r == er && curr.c == ec) {
                val path = mutableListOf<Pair<Int, Int>>()
                var temp: Node? = curr
                while (temp != null) {
                    path.add(temp.r to temp.c)
                    temp = temp.parent
                }
                return path.reversed()
            }

            open.remove(curr)
            closed.add(curr.r to curr.c)

            val directions = listOf(
                0 to 1,
                0 to -1,
                1 to 0,
                -1 to 0,
                1 to 1,
                1 to -1,
                -1 to 1,
                -1 to -1
            )

            for ((dr, dc) in directions) {
                val nr = curr.r + dr
                val nc = curr.c + dc

                if (nr !in 0 until ROWS || nc !in 0 until COLS) continue
                if (!grid[nr][nc]) continue
                if (nr to nc in closed) continue

                val moveCost = if (dr != 0 && dc != 0) 14 else 10
                val newG = curr.g + moveCost

                if (newG < gCost[nr][nc]) {
                    gCost[nr][nc] = newG
                    val h = (abs(nr - er) + abs(nc - ec)) * 10

                    val node = Node(nr, nc)
                    node.parent = curr
                    node.g = newG
                    node.h = h

                    val existing = open.find { it.r == nr && it.c == nc }
                    if (existing != null) {
                        existing.g = newG
                        existing.h = h
                        existing.parent = curr
                    } else {
                        open.add(node)
                    }
                }
            }
        }
        return emptyList()
    }
}


// подключение геопозиции
fun geoToGrid(
    userLat: Double,
    userLon: Double,
    rows: Int = ROWS,
    cols: Int = COLS
): Pair<Int, Int>? {

    val latTop = 56.46594
    val latBottom = 56.471736
    val lonLeft = 84.939305
    val lonRight = 84.954786

    if (userLat !in latBottom..latTop || userLon !in lonLeft..lonRight){
        return null
    }

    val latNorm = (userLat - latBottom) / (latTop - latBottom)
    val lonNorm = (userLon - lonLeft) / (lonRight - lonLeft)

    val row = ((1 - latNorm) * rows).toInt().coerceIn(0, rows - 1)
    val col = (lonNorm * cols).toInt().coerceIn(0, cols - 1)

    return row to col
}


