@Composable
fun Controls(
    modifier: Modifier,
    showGrid: Boolean,
    editMode: Boolean,
    foodEditMode: FoodEditMode,
    clusteringMode: Boolean,
    clusterCountText: String,
    selectedPointsCount: Int,
    onClusterCountChange: (String) -> Unit,
    onGridClick: () -> Unit,
    onEditClick: () -> Unit,
    onFoodAddClick: () -> Unit,
    onFoodDeleteClick: () -> Unit,
    onExportClick: () -> Unit,
    onClusteringToggle: () -> Unit,
    onRunClustering: () -> Unit,
    isErasing: Boolean,
    onToggleErasing: () -> Unit
) {
    val scrollState = rememberScrollState()

    Column(
        modifier = modifier
            .fillMaxWidth()
            .background(Color(0xFFF2F2F2))
            .verticalScroll(scrollState)
            .padding(12.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Row(

            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceEvenly,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(onClick = onGridClick) {
                Text(if (showGrid) "Скрыть сетку" else "Сетка")
            }
            Button(onClick = onEditClick) {
                Text(if (editMode) "Просмотр" else "Править путь")
            }
            Button(onClick = onExportClick) {
                Text("Log")
            }
            Button(onClick = onToggleErasing) {
                Text(if (isErasing) "Ластик ВКЛ" else "Ластик")
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceEvenly,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(onClick = onFoodAddClick) {
                Text(if (foodEditMode == FoodEditMode.ADD) "Добавление ВКЛ" else "Добавить общепит")
            }
            Button(onClick = onFoodDeleteClick) {
                Text(if (foodEditMode == FoodEditMode.DELETE) "Удаление ВКЛ" else "Удалить общепит")
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Center
        ) {
            Button(onClick = onClusteringToggle) {
                Text(if (clusteringMode) "Вернуться к карте" else "Кластеризация")
            }
        }

        if (clusteringMode) {
            OutlinedTextField(
                value = clusterCountText,
                onValueChange = onClusterCountChange,
                label = { Text("Количество кластеров K") },
                singleLine = true,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                modifier = Modifier.fillMaxWidth()
            )

            Text("Выбрано точек: $selectedPointsCount", fontSize = 14.sp)

            Button(
                onClick = onRunClustering,
                modifier = Modifier.fillMaxWidth()
            ) {
                Text("Запустить K-средних")
            }
        }

        Spacer(modifier = Modifier.height(12.dp))
    }
}

@Composable
fun UniversityMap(
    modifier: Modifier = Modifier,
    externalPath: List<Pair<Int, Int>>,
    showGrid: Boolean,
    editMode: Boolean,
    isErasing: Boolean,
    grid: Array<BooleanArray>,
    foodPlaces: List<Obshepit>,
    foodEditMode: FoodEditMode,
    clusteringMode: Boolean,
    selectedClusterPoints: List<ClusterPoint>,
    clusteredPoints: List<ClusteredPoint>,
    onGridChanged: () -> Unit,
    onAddFoodPlace: (Int, Int) -> Unit,
    onDeleteFoodPlace: (Int, Int) -> Unit,
    onClusterPointToggle: (Int, Int) -> Unit,
    userCell: Pair<Int, Int>?
) {
    var scale by remember { mutableStateOf(1f) }
    var offset by remember { mutableStateOf(Offset.Zero) }
    var startPoint by remember { mutableStateOf<Pair<Int, Int>?>(null) }
    var endPoint by remember { mutableStateOf<Pair<Int, Int>?>(null) }
    var path by remember { mutableStateOf<List<Pair<Int, Int>>>(emptyList()) }
        // userCell by remember { mutableStateOf<Pair<Int, Int>?>(null) }
    var selectedFoodPlace by remember { mutableStateOf<Obshepit?>(null) }

    var localGrid by remember { mutableStateOf(grid) }

    LaunchedEffect(grid) {
        localGrid = grid.map { it.copyOf() }.toTypedArray()
    }

    val clusterColors = listOf(
        Color.Red,
        Color.Blue,
        Color.Green,
        Color.Magenta,
        Color.Cyan,
        Color.Yellow,
        Color(0xFFFF9800),
        Color(0xFF9C27B0),
        Color(0xFF795548),
        Color(0xFF009688)
    )

    BoxWithConstraints(
        modifier = modifier
            .fillMaxWidth()
            .clipToBounds()
    ) {
        val density = LocalDensity.current
        val screenW = constraints.maxWidth.toFloat()
        val screenH = constraints.maxHeight.toFloat()

        val imgRatio = IMG_W / IMG_H
        val screenRatio = screenW / screenH
        val mapW = if (imgRatio > screenRatio) screenW else screenH * imgRatio
        val mapH = if (imgRatio > screenRatio) screenW / imgRatio else screenH
        val minScale = maxOf(screenW / mapW, screenH / mapH)
        val finalPath = if (externalPath.isNotEmpty()) externalPath else path

        fun fixOffset(s: Float, o: Offset): Offset {
            val maxX = maxOf((mapW * s - screenW) / 2f, 0f)
            val maxY = maxOf((mapH * s - screenH) / 2f, 0f)
            return Offset(
                o.x.coerceIn(-maxX, maxX),
                o.y.coerceIn(-maxY, maxY)
            )
        }

        fun getGridCoords(tap: Offset): Pair<Int, Int>? {
            val x = (tap.x - screenW / 2f - offset.x) / scale + mapW / 2f
            val y = (tap.y - screenH / 2f - offset.y) / scale + mapH / 2f
            val c = (x / mapW * COLS).toInt()
            val r = (y / mapH * ROWS).toInt()
            return if (r in 0 until ROWS && c in 0 until COLS) r to c else null
        }

        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(Unit) {
                    detectTransformGestures { _, pan, zoom, _ ->
                        scale = (scale * zoom).coerceIn(minScale, 5f)
                        offset = fixOffset(scale, offset + pan)
                    }
                }
                .pointerInput(editMode, isErasing, screenW, screenH, offset, scale, foodPlaces, foodEditMode, clusteringMode, selectedClusterPoints) {
                    if (editMode) {
                        detectDragGestures { change, _ ->
                            getGridCoords(change.position)?.let { (r, c) ->

                                val newGrid = localGrid.map { it.copyOf() }.toTypedArray()

                                if (isErasing) {
                                    if (localGrid[r][c]) {
                                        newGrid[r][c] = false
                                        localGrid = newGrid
                                        grid[r][c] = false
                                        onGridChanged()
                                    }
                                } else {
                                    if (!localGrid[r][c]) {
                                        newGrid[r][c] = true
                                        localGrid = newGrid
                                        grid[r][c] = true
                                        onGridChanged()
                                    }
                                }
                                if ((startPoint?.first == r && startPoint?.second == c) ||
                                    (endPoint?.first == r && endPoint?.second == c)) {
                                    startPoint = null
                                    endPoint = null
                                    path = emptyList()
                                }
                            }
                        }
                    } else {
                        detectTapGestures { tap ->
                            getGridCoords(tap)?.let { (r, c) ->

                                if (clusteringMode) {
                                    onClusterPointToggle(r, c)
                                    return@detectTapGestures
                                }

                                when (foodEditMode) {
                                    FoodEditMode.ADD -> {
                                        onAddFoodPlace(r, c)
                                        selectedFoodPlace = foodPlaces.find { it.row == r && it.col == c }
                                    }

                                    FoodEditMode.DELETE -> {
                                        onDeleteFoodPlace(r, c)
                                        if (selectedFoodPlace?.row == r && selectedFoodPlace?.col == c) {
                                            selectedFoodPlace = null
                                        }
                                    }

                                    FoodEditMode.NONE -> {
                                        val clickedFoodPlace =
                                            foodPlaces.find { it.row == r && it.col == c }
                                        selectedFoodPlace = clickedFoodPlace

                                        if (localGrid[r][c]) {
                                            if (startPoint == null || (startPoint != null && endPoint != null)) {
                                                startPoint = r to c
                                                endPoint = null
                                                path = emptyList()
                                            } else {
                                                endPoint = r to c
                                                path = AStarPathfinder(localGrid).findPath(
                                                    startPoint!!.first,
                                                    startPoint!!.second,
                                                    r,
                                                    c
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
            contentAlignment = Alignment.Center
        ) {
            Box(
                modifier = Modifier
                    .width(with(density) { mapW.toDp() })
                    .height(with(density) { mapH.toDp() })
                    .graphicsLayer {
                        scaleX = scale
                        scaleY = scale
                        translationX = offset.x
                        translationY = offset.y
                    }
            ) {
                Image(
                    painter = painterResource(R.drawable.map_university),
                    contentDescription = null,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.FillBounds
                )

                Canvas(modifier = Modifier.fillMaxSize()) {
                    val cw = size.width / COLS
                    val ch = size.height / ROWS

                    if (showGrid) {
                        for (r in 0 until ROWS) {
                            for (c in 0 until COLS) {
                                if (!localGrid[r][c]) {
                                    drawRect(
                                        color = Color.Red.copy(alpha = 0.35f),
                                        topLeft = Offset(c * cw, r * ch),
                                        size = Size(cw, ch)
                                    )
                                } else {
                                    drawRect(
                                        color = Color.White.copy(alpha = 0.2f),
                                        topLeft = Offset(c * cw, r * ch),
                                        size = Size(cw, ch)
                                    )
                                }
                            }
                        }
                    }

                    path.forEach { (r, c) ->
                        drawRect(
                            color = Color(0xFF4CAF50),
                            topLeft = Offset(c * cw, r * ch),
                            size = Size(cw, ch)
                        )
                    }
                    externalPath.forEach { (r, c) ->
                        drawRect(
                            color = Color.Blue,
                            topLeft = Offset(c * cw, r * ch),
                            size = Size(cw, ch)
                        )
                    }

                    foodPlaces.forEach { place ->
                        drawRect(
                            color = Color.Yellow.copy(alpha = 0.8f),
                            topLeft = Offset(place.col * cw, place.row * ch),
                            size = Size(cw, ch)
                        )
                    }

                    userCell?.let { (r, c) ->
                        drawRect(
                            color = Color.Red.copy(alpha = 0.9f),
                            topLeft = Offset(c * cw, r * ch),
                            size = Size(cw, ch)
                        )
                    }

                    if (clusteredPoints.isNotEmpty()) {
                        clusteredPoints.forEach { point ->
                            drawRect(
                                color = clusterColors[point.clusterIndex % clusterColors.size].copy(alpha = 0.85f),
                                topLeft = Offset(point.col * cw, point.row * ch),
                                size = Size(cw, ch)
                            )
                        }
                    } else {
                        selectedClusterPoints.forEach { point ->
                            drawRect(
                                color = Color.Black.copy(alpha = 0.85f),
                                topLeft = Offset(point.col * cw, point.row * ch),
                                size = Size(cw, ch)
                            )
                        }
                    }

                    startPoint?.let { (r, c) ->
                        drawCircle(
                            color = Color.Blue,
                            radius = cw / 2,
                            center = Offset(c * cw + cw / 2, r * ch + ch / 2)
                        )
                    }

                    endPoint?.let { (r, c) ->
                        drawCircle(
                            color = Color.Magenta,
                            radius = cw / 2,
                            center = Offset(c * cw + cw / 2, r * ch + ch / 2)
                        )
                    }
                }

                selectedFoodPlace?.let { place ->
                    val cellW = mapW / COLS
                    val cellH = mapH / ROWS

                    Text(
                        text = place.title,
                        color = Color.Black,
                        fontSize = 12.sp,
                        modifier = Modifier
                            .offset(
                                x = with(density) { (place.col * cellW + 6f).toDp() },
                                y = with(density) { (place.row * cellH - 18f).toDp() }
                            )
                            .background(Color.White.copy(alpha = 0.9f))
                            .padding(4.dp)
                    )
                }
            }
        }
    }
    val MAP_LAT_TOP = 56.46594
    val MAP_LAT_BOTTOM = 56.471736
    val MAP_LON_LEFT = 84.939305
    val MAP_LON_RIGHT = 84.954786


}